1	<?php
2	
3	require(__DIR__ . '/includes/session.php');
4	
5	$Title = __('Credit Status Code Maintenance');
6	$ViewTopic = 'CreditStatus';
7	$BookMark = 'CreditStatus';
8	include('includes/header.php');
9	
10	if (isset($_GET['SelectedReason'])){
11		$SelectedReason = $_GET['SelectedReason'];
12	} elseif (isset($_POST['SelectedReason'])){
13		$SelectedReason = $_POST['SelectedReason'];
14	}
15	
16	$Errors = array();
17	$InputError = 0;
18	echo '<p class="page_title_text">
19			<img src="'.$RootPath.'/css/'.$Theme.'/images/maintenance.png" title="' . __('Search') . '" alt="" />' . ' ' . $Title.'
20		</p>
21		<br />';
22	
23	if (isset($_POST['submit'])) {
24	
25		//initialise no input errors assumed initially before we test
26		$i=1;
27	
28		/* actions to take once the user has clicked the submit button
29		ie the page has called itself with some user input */
30	
31		//first off validate inputs are sensible
32	
33		$SQL="SELECT count(reasoncode)
34				FROM holdreasons WHERE reasoncode='".$_POST['ReasonCode']."'";
35		$Result = DB_query($SQL);
36		$MyRow=DB_fetch_row($Result);
37	
38		if ($MyRow[0]!= 0 and !isset($SelectedReason)) {
39			$InputError = 1;
40			prnMsg( __('The credit status code already exists in the database'),'error');
41			$Errors[$i] = 'ReasonCode';
42			$i++;
43		}
44		if (!is_numeric($_POST['ReasonCode'])) {
45			$InputError = 1;
46			prnMsg(__('The status code name must be an integer'),'error');
47			$Errors[$i] = 'ReasonCode';
48			$i++;
49		}
50		if (mb_strlen($_POST['ReasonDescription']) > 30) {
51			$InputError = 1;
52			prnMsg(__('The credit status description must be thirty characters or less long'),'error');
53		}
54		if (mb_strlen($_POST['ReasonDescription']) == 0) {
55			$InputError = 1;
56			prnMsg(__('The credit status description must be entered'),'error');
57			$Errors[$i] = 'ReasonDescription';
58			$i++;
59		}
60	
61		$Msg='';
62	
63		if (isset($SelectedReason) AND $InputError != 1) {
64	
65			/*SelectedReason could also exist if submit had not been clicked this code would not run in this case cos submit is false of course	see the delete code below*/
66	
67			if (isset($_POST['DisallowInvoices']) and $_POST['DisallowInvoices']=='on'){
68				$SQL = "UPDATE holdreasons SET
69								reasondescription='" . $_POST['ReasonDescription'] . "',
70								dissallowinvoices=1
71								WHERE reasoncode = '".$SelectedReason."'";
72			} else {
73				$SQL = "UPDATE holdreasons SET
74								reasondescription='" . $_POST['ReasonDescription'] . "',
75								dissallowinvoices=0
76								WHERE reasoncode = '".$SelectedReason."'";
77			}
78			$Msg = __('The credit status record has been updated');
79	
80		} elseif ($InputError != 1) {
81	
82		/*Selected Reason is null cos no item selected on first time round so must be adding a record must be submitting new entries in the new status code form */
83	
84			if (isset($_POST['DisallowInvoices']) AND $_POST['DisallowInvoices']=='on'){
85	
86				$SQL = "INSERT INTO holdreasons (reasoncode,
87												reasondescription,
88												dissallowinvoices)
89										VALUES ('" .$_POST['ReasonCode'] . "',
90												'".$_POST['ReasonDescription'] . "',
91												1)";
92			} else {
93				$SQL = "INSERT INTO holdreasons (reasoncode,
94												reasondescription,
95												dissallowinvoices)
96										VALUES ('" . $_POST['ReasonCode'] . "',
97												'" . $_POST['ReasonDescription'] ."',
98												0)";
99			}
100	
101			$Msg = __('A new credit status record has been inserted');
102		}
103		//run the SQL from either of the above possibilites
104		$Result = DB_query($SQL);
105		if ($Msg !=  '') {
106			prnMsg($Msg,'success');
107		}
108		unset ($SelectedReason);
109		unset ($_POST['ReasonCode']);
110		unset ($_POST['ReasonDescription']);
111		unset ($_POST['submit']);
112	} elseif (isset($_GET['delete'])) {
113	//the link to delete a selected record was clicked instead of the submit button
114	
115	// PREVENT DELETES IF DEPENDENT RECORDS IN DebtorsMaster
116	
117		$SQL= "SELECT COUNT(*)
118				FROM debtorsmaster
119				WHERE debtorsmaster.holdreason='".$SelectedReason."'";
120	
121		$Result = DB_query($SQL);
122		$MyRow = DB_fetch_row($Result);
123		if ($MyRow[0] > 0) {
124			prnMsg( __('Cannot delete this credit status code because customer accounts have been created referring to it'),'warn');
125			echo '<br />' . __('There are') . ' ' . $MyRow[0] . ' ' . __('customer accounts that refer to this credit status code');
126		}  else {
127			//only delete if used in neither customer or supplier accounts
128	
129			$SQL="DELETE FROM holdreasons WHERE reasoncode='" . $SelectedReason . "'";
130			$Result = DB_query($SQL);
131			prnMsg(__('This credit status code has been deleted'),'success');
132		}
133		//end if status code used in customer or supplier accounts
134		unset ($_GET['delete']);
135		unset ($SelectedReason);
136	
137	}
138	
139	if (!isset($SelectedReason)) {
140	
141	/* It could still be the second time the page has been run and a record has been selected for modification - SelectedReason will exist because it was sent with the new call. If its the first time the page has been displayed with no parameters
142	then none of the above are true and the list of status codes will be displayed with
143	links to delete or edit each. These will call the same page again and allow update/input
144	or deletion of the records*/
145	
146		$SQL = "SELECT reasoncode, reasondescription, dissallowinvoices FROM holdreasons";
147		$Result = DB_query($SQL);
148	
149		echo '<table class="selection">
150			<tr>
151				<th>' .  __('Status Code')  . '</th>
152				<th>' .  __('Description')  . '</th>
153				<th>' .  __('Disallow Invoices')  . '</th>
154				<th colspan="2"></th>
155	        </tr>';
156	
157		while ($MyRow=DB_fetch_array($Result)) {
158	
159			if ($MyRow['dissallowinvoices']==0) {
160				$DissallowText = __('Invoice OK');
161			} else {
162				$DissallowText = '<b>' .  __('NO INVOICING')  . '</b>';
163			}
164	
165			echo '<tr class="striped_row">
166					<td>', $MyRow['reasoncode'], '</td>
167					<td>', $MyRow['reasondescription'], '</td>
168					<td>', $DissallowText, '</td>
169					<td><a href="', htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8'), '?SelectedReason=', $MyRow['reasoncode'], '">' . __('Edit') . '</a></td>
170					<td><a href="', htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8'), '?SelectedReason=', $MyRow['reasoncode'], '&amp;delete=1" onclick="return confirm(\'' . __('Are you sure you wish to delete this credit status record?') . '\');">' .  __('Delete')  . '</a></td>
171				</tr>';
172	
173		} //END WHILE LIST LOOP
174		echo '</table>';
175	
176	} //end of ifs and buts!
177	
178	if (isset($SelectedReason)) {
179		echo '<div class="centre">
180				<a href="' . htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8') . '">' . __('Show Defined Credit Status Codes') . '</a>
181			</div>';
182	}
183	
184	if (!isset($_GET['delete'])) {
185	
186		echo '<form method="post" action="' . htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8') . '">';
187		echo '<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />';
188	
189		if (isset($SelectedReason) and ($InputError!= 1)) {
190			//editing an existing status code
191	
192			$SQL = "SELECT reasoncode,
193						reasondescription,
194						dissallowinvoices
195					FROM holdreasons
196					WHERE reasoncode='".$SelectedReason."'";
197	
198			$Result = DB_query($SQL);
199			$MyRow = DB_fetch_array($Result);
200	
201			$_POST['ReasonCode'] = $MyRow['reasoncode'];
202			$_POST['ReasonDescription']  = $MyRow['reasondescription'];
203			$_POST['DisallowInvoices']  = $MyRow['dissallowinvoices'];
204	
205			echo '<input type="hidden" name="SelectedReason" value="' . $SelectedReason . '" />';
206			echo '<input type="hidden" name="ReasonCode" value="' . $_POST['ReasonCode'] . '" />';
207			echo '<fieldset>
208					<legend>', __('Edit Credit Status'), '</legend>
209					<field>
210						<label for="ReasonCode">' .  __('Status Code') .':</label>
211						<fieldtext>' . $_POST['ReasonCode'] . '</fieldtext>
212					</field>';
213	
214		} else { //end of if $SelectedReason only do the else when a new record is being entered
215			if (!isset($_POST['ReasonCode'])) {
216				$_POST['ReasonCode'] = '';
217			}
218			echo '<fieldset>
219					<legend>', __('Create Credit Status'), '</legend>
220					<field>
221						<label for="ReasonCode">' .  __('Status Code') .':</label>
222						<input ' . (in_array('ReasonCode',$Errors) ? 'class="integer inputerror"' : 'class="integer"' ) . ' tabindex="1" type="text" name="ReasonCode" required="required" value="'. $_POST['ReasonCode'] .'" size="3" maxlength="2" />
223					</field>';
224		}
225	
226		if (!isset($_POST['ReasonDescription'])) {
227			$_POST['ReasonDescription'] = '';
228		}
229		echo '<field>
230				<label for="ReasonDescription">' .  __('Description') .':</label>
231				<input ' . (in_array('ReasonDescription',$Errors) ? 'class="inputerror"' : '' ) .
232				 ' tabindex="2" type="text" name="ReasonDescription" required="required" value="'. $_POST['ReasonDescription'] .'" size="28" maxlength="30" />
233			</field>
234			<field>
235				<label for="DisallowInvoices">' .  __('Disallow Invoices') . '</label>';
236		if (isset($_POST['DisallowInvoices']) and $_POST['DisallowInvoices']==1) {
237			echo '<input tabindex="3" type="checkbox" checked="checked" name="DisallowInvoices" />
238				</field>';
239		} else {
240			echo '<input tabindex="3" type="checkbox" name="DisallowInvoices" />
241				</field>';
242		}
243		echo '</fieldset>
244				<div class="centre">
245					<input tabindex="4" type="submit" name="submit" value="' . __('Enter Information') . '" />
246	            </div>
247				</form>';
248	} //end if record deleted no point displaying form to add record
249	include('includes/footer.php');
250

